import React, { useEffect, useState } from 'react';
import {
  Box,
  Container,
  ThemeProvider,
  createTheme,
  CssBaseline,
  CircularProgress,
  Stack,
  Typography,
} from '@mui/material';

import PatientDetails from '../components/PdfViewerAndQuestions/PatientDetails';
import ClinicalGuidelinesModal from '../components/PdfViewerAndQuestions/ClinicalGuidelinesModals';
import ClinicalQuestion from '../components/PdfViewerAndQuestions/ClinicalQuestion';
import PdfDetail from '../components/PdfViewerAndQuestions/PdfDetail';
import { observer } from 'mobx-react-lite';
import { mainPageStore } from '../stores/MainPageStore';
import { toJS } from 'mobx';
import { useLocation, useParams } from 'react-router-dom';
import { CheckIcon } from 'lucide-react';


// Create Material-UI theme
const theme = createTheme({
  palette: {
    primary: {
      main: '#0F4977',
    },
    secondary: {
      main: '#FB4E0B',
    },
  },
  typography: {
    fontFamily: 'Roboto, Inter, Arial, sans-serif',
  },
});

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

const steps = [
  "Gathering your prior authorization and healthcare utilization records to personalize your experience.",
  "Securely analyzing your records to pre-fill your clinical questionnaire for a faster review."
];

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`tabpanel-${index}`}
      aria-labelledby={`tab-${index}`}
      style={{ height: '100%' }}
      {...other}
    >
      {value === index && <Box sx={{ height: '100%' }}>{children}</Box>}
    </div>
  );
}

const PdfViewerAndQuestionPage = () => {
  const { fetchClinicalAssesmentData, fetchClinicalAssesmentDataUsingPost } = mainPageStore;

  const { patient_id, procedure_name } = useParams<{ patient_id?: string; procedure_name?: string }>();

  useEffect(() => {
    if (patient_id && procedure_name) {
      fetchClinicalAssesmentData(patient_id, procedure_name);
    }
  }, [patient_id, procedure_name]);

  const location = useLocation();
  const [showProgressBar, setShowProgressBar] = useState<boolean>(false);


  useEffect(() => {
    const flagFromNav = Boolean((location.state as any)?.showProgressBar);
    setShowProgressBar(flagFromNav);
  }, [location.state]);


  const clinicalEhrData = mainPageStore.clinicalAssesmentEhrData;
  const [currentTab, setCurrentTab] = useState(0);
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedPatientId] = useState(1);
  const currentPatient = clinicalEhrData?.slice(0, 2);
  const [activeStep, setActiveStep] = useState(0);
  const [done, setDone] = useState(false);

  const handleCloseModal = () => {
    setModalOpen(false);
  };

  const handleNextModal = () => {
    setModalOpen(false);
  };

  useEffect(() => {
    if (activeStep < 2) {
      const timer = setTimeout(() => setActiveStep((p) => p + 1), 6000);
      return () => clearTimeout(timer);
    } else {
      setDone(true);
    }
  }, [activeStep]);
  const shouldShow = showProgressBar ? done : true;
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      {clinicalEhrData && clinicalEhrData.length > 0 ?
        (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              minHeight: '100vh', // allows page to grow beyond viewport
              overflowY: 'auto',  // enables vertical scrolling
              bgcolor: '#FAFAFA',
            }}
          >
            {/* Main Content */}
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
              <Container
                maxWidth={false}
                sx={{
                  flex: 1,
                  py: 1,
                  display: 'flex',
                  flexDirection: 'column',
                }}
              >
                {/* Patient Details */}
                <PatientDetails
                  patient={{
                    name: currentPatient[0]?.patient_name,
                    dob: currentPatient[0]?.demographics?.dob,
                    memberId: currentPatient[0]?.member_id,
                    gender: currentPatient[0]?.demographics?.gender,
                    submissionDate: currentPatient[0]?.pa_metadata?.submission_date,
                    insurancePlan: currentPatient[0]?.demographics?.insurance_plan,
                  }}
                />


                {/* Tab Panels */}
                <Box sx={{ flex: 1 }}>
                  <Box
                    sx={{
                      width: "100%",
                      maxWidth: 800,
                      mx: "auto",
                      mt: 1,
                      textAlign: "center",
                    }}
                  >
                    {/* --- Steps Row --- */}
                    {/* --- Steps + Lines --- */}

                    {showProgressBar && activeStep < 2 && (<Typography
                      sx={{
                        fontSize: 12,
                        fontWeight: 600,
                        // color: "green",
                      }}
                    >
                      Processing Request ... Please wait
                    </Typography>)}

                    {showProgressBar && !done && (<Box sx={{ position: "relative", px: 0 }}>

                      {/* Connecting Line */}
                      <Box
                        sx={{
                          position: "absolute",
                          top: "16px",
                          left: 0,
                          right: 0,
                          height: "2px",
                          backgroundColor: "#d3d3d3",
                          zIndex: 0
                        }}
                      />

                      {/* Progress Line */}
                      <Box
                        sx={{
                          position: "absolute",
                          top: "16px",
                          left: 0,
                          height: "2px",
                          // width: `${(activeStep / 2) * 100}%`,
                          width: `${(activeStep / (steps.length)) * 100}%`,
                          backgroundColor: "green",
                          transition: "width 0.3s ease",
                          zIndex: 1
                        }}
                      />

                      {/* Step Circles */}
                      <Stack direction="row" justifyContent="space-between">
                        {[1, 2].map((num, index) => {
                          const isCompleted = index < activeStep;
                          const isCurrent = index === activeStep;

                          return (
                            <Box
                              key={num}
                              sx={{
                                width: 35,
                                height: 35,
                                borderRadius: "50%",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                fontSize: 12,
                                fontWeight: 700,
                                color: "white",
                                backgroundColor: isCompleted ? "green" : "#e0e0e0ff",
                                position: "relative",
                                zIndex: 2,
                                transition: "0.3s ease-in-out",
                              }}
                            >
                              {/* No tickmark — only number disappears if step is completed? */}
                              {isCompleted ? <CheckIcon style={{ color: "white", fontSize: 12 }} /> : num}
                            </Box>
                          );
                        })}
                      </Stack>
                    </Box>)}

                    {/* --- Circular Loader --- */}
                    {!done && showProgressBar && (
                      <Box sx={{ mt: 4 }}>
                        <CircularProgress size={50} thickness={2} />
                      </Box>
                    )}

                    {/* --- Status Text --- */}
                    {!done && showProgressBar && (
                      <Typography sx={{ mt: 1, fontWeight: 600, fontSize: 12 }}>
                        {steps[activeStep] || ""}
                      </Typography>
                    )}

                    {/* --- After Completion Content --- */}
                    {done && showProgressBar && (
                      <Box sx={{ mt: 4 }}>
                        {/* <Typography
            sx={{
              fontSize: 18,
              fontWeight: 600,
              color: "green",
            }}
          >
            ✓ All steps completed. Showing results...
          </Typography> */}
                      </Box>
                    )}
                  </Box>





                  {shouldShow && (
                    <>
                      <TabPanel value={currentTab} index={0}>
                        <Box
                          sx={{
                            display: 'flex',
                            flexDirection: { xs: 'column', md: 'row' },
                            gap: 2,
                            minHeight: '600px', // optional: set a minimum height for content
                          }}
                        >

                          <Box
                            sx={{
                              width: { xs: '100%', md: '50%' },
                              // display: 'flex',
                              display: 'none' // change this to flex to show pdf viewer
                            }}
                          >
                            <Box
                              sx={{
                                flex: 1,
                                maxHeight: '600px',
                                // overflow: 'auto',
                                border: '1px solid rgba(0,0,0,0.12)',
                                borderRadius: '8px',
                                bgcolor: 'white',
                              }}
                            >
                              {/* <PDFViewerComponent /> */}
                              {/* <PdfDetail /> */}
                            </Box>
                          </Box>

                          <Box
                            sx={{
                              width: { xs: '100%', md: '100%' },
                              display: 'flex',
                            }}
                          >
                            <Box
                              sx={{
                                flex: 1,
                                maxHeight: '600px', // Same scroll threshold
                                overflow: 'auto',
                                border: '1px solid rgba(0,0,0,0.12)',
                                borderRadius: '8px',
                                bgcolor: 'white',
                              }}
                            >
                              <ClinicalQuestion />
                            </Box>
                          </Box>


                        </Box>
                      </TabPanel>

                      <TabPanel value={currentTab} index={1}>
                        <Box
                          sx={{
                            maxWidth: '800px',
                            mx: 'auto',
                            bgcolor: 'white',
                            p: 2,
                            borderRadius: '8px',
                            border: '1px solid rgba(0,0,0,0.12)',
                          }}
                        >
                          {/* <SummaryView questions={currentQuestions.questions} /> */}
                        </Box>
                      </TabPanel></>)}
                </Box>
              </Container>
            </Box>

            {/* Clinical Guidelines Modal */}
            <ClinicalGuidelinesModal
              open={modalOpen}
              onClose={handleCloseModal}
              onNext={handleNextModal}
            />
          </Box>
        ) : (
<Box
  sx={{
    display: 'flex',
    flexDirection: 'column', // stack vertically
    justifyContent: 'center',
    alignItems: 'center',
    height: '100%', // or a fixed height like '200px'
    textAlign: 'center',
    gap: 1, // spacing between items
  }}
>
  <Typography variant="h6" fontWeight="bold">
    Processing Request...
  </Typography>
  <Typography variant="body2" color="text.secondary">
    Please wait
  </Typography>
  <CircularProgress size={24} />
</Box>

        )}

    </ThemeProvider>

  );
}

export default observer(PdfViewerAndQuestionPage);