import React from "react";
import { observer } from "mobx-react-lite";
import { Box, CssBaseline, ThemeProvider } from "@mui/material";
import DefaultSidebar from "./DefaultSidebar";
import DefaultMiddlebar from "./DefaultMiddlebar";
import DefaultHeader from "./DefaultHeader";
import { Outlet } from "react-router-dom";
import { theme } from "./BaseLayout.style";
import { mainPageStore } from "../../stores/MainPageStore";

interface BaseLayoutProps {
  header?: React.ReactNode;
  sidebar?: React.ReactNode;
  middleBar?: React.ReactNode;
}

const HEADER_HEIGHT = 48; // match your Header height

const BaseLayout = observer((props?: BaseLayoutProps) => {
  const header = props?.header ?? <DefaultHeader />;
  const sidebar = props?.sidebar ?? <DefaultSidebar />;
  const middleBar = props?.middleBar ?? <DefaultMiddlebar />;
  const { sidebarCollapsed, middleBarCollapsed } = mainPageStore;

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />

      {/* ROOT Layout: Vertical */}
      <Box
        sx={{
          display: "flex",
          flexDirection: "column",
          //height: "100vh",
          height: "100%",
          overflow: "hidden",
        }}
      >
        {/* HEADER */}
        <Box
          sx={{
            height: `${HEADER_HEIGHT}px`,
            flexShrink: 0,
            borderBottom: "1px solid rgba(0,0,0,0.1)",
            zIndex: 10,
          }}
        >
          {header}
        </Box>

        {/* BODY: Horizontal layout of sidebar and content */}
        <Box
          sx={{
            display: "flex",
            flexGrow: 1,
            minHeight: 0, // Required to prevent layout breaking
            overflow: "hidden",
          }}
        >
          {/* SIDEBAR */}
          <Box
            sx={{
               width: sidebarCollapsed ? 0 : 240,              
              borderRight: "1px solid rgba(0,0,0,0.1)",
              overflowY: "auto",
              flexShrink: 0,
              backgroundColor: "#EAF2F7",
            }}
          >
            {sidebar}
          </Box>

           {/* MiddleBar */}
          <Box
            sx={{
               width: middleBarCollapsed ? 0 : 240,              
              borderRight: "1px solid rgba(0,0,0,0.1)",
              overflowY: "auto",
              flexShrink: 0,
              // backgroundColor: "#EAF2F7",
              backgroundColor: "#FFFFFF",
            }}
          >
            {middleBar}
          </Box>

          {/* MAIN CONTENT */}
          <Box
            sx={{
              flexGrow: 1,
              overflowY: "auto",
              padding: '2px',
              backgroundColor: "#F9FAFB",
              
            }}
          >
            <Outlet />
          </Box>
        </Box>
      </Box>
    </ThemeProvider>
  );
});

export default BaseLayout;