import React, { useEffect } from "react";
import { observer } from "mobx-react-lite";
import { useParams } from "react-router-dom";
import { mainPageStore } from "../stores/MainPageStore";
import ProviderFacilityDetail from "../components/NewProviderFacility/ProviderFacilityDetail";

const NewProviderFacilityPage = () => {
  console.log("A: Component start");

  const params = useParams();
  console.log("B: params =", params);

  const patient_id = params.patient_id;
  console.log("C: patient_id =", patient_id);

  console.log("D: Before useEffect");

  useEffect(() => {
    console.log("E: USE EFFECT FIRED!");

    if (patient_id) {
      console.log("F: Calling fetchPatientData");
      mainPageStore.fetchPatientData(patient_id);
    }
  }, [patient_id]);

  console.log("G: Component end (before return)");

  console.log(mainPageStore.patientformData);

  // return <div>TEST PAGE</div>;
   
   return mainPageStore.patientformData && (<ProviderFacilityDetail  patientformData={mainPageStore.patientformData}/>)
}


export default observer(NewProviderFacilityPage);