import React, { useState, useMemo, useEffect } from 'react';
import { observer } from "mobx-react-lite";
import { mainPageStore } from '../stores/MainPageStore';
import { Box, CssBaseline, ThemeProvider, createTheme } from '@mui/material';
import FilterPanel from '../components/Dashboard/FilterPanel';
import QuickActions from '../components/Dashboard/QuickActions';
import AuthorizationRequestTable from '../components/Dashboard/AuthorizationRequestTable';
import {  useNavigate } from 'react-router-dom';


const HomePage = () => {
 const {fetchPriorAuthHomeData,homeData} = mainPageStore;
 const [selectedStatus, setSelectedStatus] = useState<string>('all');
 const navigate = useNavigate();

  useEffect(()=>{
    fetchPriorAuthHomeData();
  },[])
  
  const [searchFields, setSearchFields] = useState({
    memberId: '',
    trackingId: '',
    authorizationId: '',
    authorizationId2: '',
  });

  // Pagination states
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);

  // Handle status filter change
  const handleStatusChange = (status: string) => {
    setSelectedStatus(status);
    setPage(0); // Reset to first page when filter changes
  };

  // Handle search field change
  const handleSearchFieldChange = (field: string, value: string) => {
    setSearchFields((prev) => ({
      ...prev,
      [field]: value,
    }));
    setPage(0); // Reset to first page when search changes
  };

    // Filter data based on status and search fields
  const filteredData = useMemo(() => {
    let filtered = homeData || [];
    console.log('selectedStatus',selectedStatus);
    // Filter by status
    if (selectedStatus !== 'all') {
      filtered = filtered.filter((item: { Status: string; }) => item.Status === selectedStatus);
    }

    // Filter by search fields
    if (searchFields.memberId) {
      filtered = filtered.filter((item:any) =>
        item["Member ID"].toLowerCase().includes(searchFields.memberId.toLowerCase())
      );
    }

    if (searchFields.trackingId) {
      filtered = filtered.filter((item: any) =>
        item['Tracking ID'].toLowerCase().includes(searchFields.trackingId.toLowerCase())
      );
    }

    if (searchFields.authorizationId ) {
      // const searchTerm = searchFields.authorizationId ;
      // filtered = filtered.filter(
      //   (item: { id: { toString: () => string | string[]; }; procedure: string; }) =>
      //     item.id.toString().includes(searchTerm) ||
      //     item.procedure.toLowerCase().includes(searchTerm.toLowerCase())
      // );
      filtered = filtered.filter((item: any) =>
        item['Authorization ID'].toLowerCase().includes(searchFields.authorizationId.toLowerCase())
      );

    }
    return filtered;
  }, [selectedStatus, searchFields,homeData]);

  // Handle pagination
  const handlePageChange = (_event: unknown, newPage: number) => {
    setPage(newPage);
  };

  const handleRowsPerPageChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  // Handle quick actions
  const handleNewRequest = () => {
  
    // console.log('New Authorization Request clicked');
    // alert('New Authorization Request functionality');
    navigate('/pharmacy-portal/patient-procedure-info');
  };

  const handleViewAllRequests = () => {
    console.log('View All Requests clicked');
    setSelectedStatus('all');
    setRowsPerPage(50);
    setSearchFields({
      memberId: '',
      trackingId: '',
      authorizationId: '',
      authorizationId2: '',
    });
    setPage(0);
  };


  return (
    <div
      style={{
        backgroundColor: '#fff',
        minHeight: '100vh',
         padding: '13px',
      }}
    >
      <div
        style={{
          display: 'flex',
          // gap: '16px',
          gap: '6px',
          // maxWidth: '1400px',
          // margin: '0 auto',
        }}
      >
        {/* Left Sidebar - Filter Panel */}
        <div style={{ flexShrink: 0 }}>
          <FilterPanel
            selectedStatus={selectedStatus}
            onStatusChange={handleStatusChange}
            searchFields={searchFields}
            onSearchFieldChange={handleSearchFieldChange}
            handleViewAllRequests={handleViewAllRequests}
          />
        </div>

        {/* Main Content Area */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '16px' }}>
          {/* Quick Actions */}
          <QuickActions
            onNewRequest={handleNewRequest}
            onViewAllRequests={handleViewAllRequests}
          />

          {/* Authorization Request Table */}
          <AuthorizationRequestTable
            data={filteredData}
            page={page}
            rowsPerPage={rowsPerPage}
            onPageChange={handlePageChange}
            onRowsPerPageChange={handleRowsPerPageChange}
          />
        </div>
      </div>
    </div>
  );
};

export default observer(HomePage);