import React, { useEffect, useState } from "react";
import { observer } from "mobx-react-lite";
import {
  Box,
  List,
  ListItemText,
  Collapse,
  ListItemButton,
} from "@mui/material";
import {
  ExpandLess,
  ExpandMore,
  ArticleOutlined,
  NoteOutlined,
  CallOutlined
} from "@mui/icons-material";
import { useLocation, useNavigate } from "react-router-dom";
import NavItem from "./NavItem";
import { mainPageStore } from "../../stores/MainPageStore";
import { ChevronLeft, ChevronRight, PlusIcon } from "lucide-react";

type Solution = "legacy_pricing_logic";

interface ModuleFeature {
  icon: React.ReactNode;
  label: string;
  route: string;
  subItems?: { icon: React.ElementType; label: string; href: string }[];
}

// -------------------- FEATURE CONFIG --------------------
const moduleFeatures: Record<Solution, ModuleFeature[]> = {
  legacy_pricing_logic: [
    { icon: <PlusIcon />, label: "Dashboard", route: "/" },
    // { icon: <NoteOutlined />, label: "View All Requests", route: "/" },
    // { icon: <ArticleOutlined />, label: "Upload Clinical Documents", route: "/" },
    // { icon: <CallOutlined />, label: "------------------------------------------", route: "#" },
    { icon: <ArticleOutlined />, label: "New Dashboard", route: "/new/pro" },
  ],
};

// -------------------- SIDEBAR --------------------
const Sidebar = observer(() => {
  const [expandedModule, setExpandedModule] = useState<string>("Module 1");

  const navigate = useNavigate();
  const location = useLocation();

  const groupedModules = {
    "Module Features": moduleFeatures.legacy_pricing_logic, // Contract Shell Builder, Configure Services, Pricing Contract
  };

  const toggleModule = (moduleName: string) => {
    setExpandedModule((prev) => (prev === moduleName ? "" : moduleName));
  };

  const toggleSidebar = () => {
    mainPageStore.setSidebarCollapsed();
  };

  // Auto-expand based on route
  useEffect(() => {
    Object.entries(groupedModules).forEach(([moduleName, items]) => {
      if (items.some((f) => location.pathname.startsWith(f.route))) {
        setExpandedModule(moduleName);
      }
    });
  }, [location.pathname]);

  // -------------------- RENDER --------------------
  return (
    <Box
      display="flex"
      flexDirection="column"
      height="94vh"
      bgcolor="#EAF2F7"
      fontFamily="Montserrat, sans-serif"
    >
      <Box flexGrow={1}>
        <List sx={{ padding: 0 }}>
          {/* Modules */}
          {Object.entries(groupedModules).map(([moduleName, items]) => (
            <React.Fragment key={moduleName}>
              {/* <ListItemButton onClick={() => toggleModule(moduleName)}> */}
                <ListItemButton onClick={toggleSidebar}>
                <ListItemText
                  primary={moduleName}
                  primaryTypographyProps={{ fontSize: "13px", fontWeight: 500 }}
                />
                {expandedModule === moduleName ? <ChevronLeft  /> : <ChevronRight />}
              </ListItemButton>

              {/* <Collapse in={expandedModule === moduleName} timeout="auto" unmountOnExit> */}
              <Collapse in={true} timeout="auto" unmountOnExit>
                <List component="div" disablePadding>
                  {items.map((feature) => (
                    <NavItem
                      key={feature.label}
                      icon={feature.icon}
                      label={feature.label}
                      collapsed={false}
                      onClick={() => {
                        mainPageStore.setMiddleBarItems(
                          feature.subItems ?? [],
                          feature.label
                        );
                        navigate(feature.route);
                      }}
                    />
                  ))}
                </List>
              </Collapse>
            </React.Fragment>
          ))}
        </List>
      </Box>
    </Box>
  );
});

export default Sidebar;
