import React, { ReactNode } from "react";
import {
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
  Box,
} from "@mui/material";

interface NavItemProps {
  icon: string | ReactNode;
  label: string;
  collapsed?: boolean;
  onClick?: () => void | Promise<void>;
}

const NavItem: React.FC<NavItemProps> = ({
  icon,
  label,
  collapsed = false,
  onClick,
}) => {
  return (
    <Box>
      <ListItemButton onClick={onClick} sx={{ paddingTop: 0 }}>
        <ListItemIcon
          sx={{ minWidth: 32, color: "black", fontWeight: 200, opacity: 0.7 }}
        >
          {typeof icon === "string" ? (
            <img src={icon} alt={label} width={20} height={20} />
          ) : (
            icon
          )}
        </ListItemIcon>

        {!collapsed && (
          <ListItemText
            sx={{ marginBottom: 0 }}
            primary={<Typography sx={{ fontSize: "14px" }}>{label}</Typography>}
          />
        )}
      </ListItemButton>
    </Box>
  );
};

export default NavItem;
