import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Radio,
  RadioGroup,
  FormControlLabel,
  FormControl,
  Button,
  Paper,
} from '@mui/material';
import { observer } from "mobx-react-lite";
import { useNavigate, useParams } from 'react-router-dom';
import { mainPageStore } from '../../stores/MainPageStore';
import { toJS } from 'mobx';

const Summary = () => {
  const { pa_status, procedure_name,patient_id } = useParams<{ pa_status?: string; procedure_name?: string,patient_id?:string }>();
  const navigate = useNavigate();

  const sortedQuestions = mainPageStore.visitedClinicalAssesment;
  console.log('visitedClinicalAssesment', toJS(sortedQuestions));

  if (!sortedQuestions || sortedQuestions.length == 0) {
    return <Box sx={{ textAlign: "center" }}>No data available</Box>;
  }

  return (
    <Box sx={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column' }}>
      {/* Header */}
      <Box
        sx={{
          bgcolor: '#EAF2F7',
          p: 1,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          borderBottom: '1px solid rgba(0,0,0,0.1)',
        }}
      >
        <Typography
          sx={{
            fontFamily: 'Roboto',
            fontSize: '14px',
            fontWeight: 500,
            color: '#000',
          }}
        >
          Summary: Clinical Assessment Responses
        </Typography>
      </Box>

      {/* Questions Content */}
      <Box
        sx={{
          flex: 1,
          overflow: 'auto',
          bgcolor: '#FAFAFA',
          p: 2,
        }}
      >
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          {/* {questions.map((question, index) => ( */}
          {sortedQuestions.map((answer: any) => (
            <Paper
              key={answer.q_id}
              elevation={0}
              sx={{
                border: '1px solid #E0E0E0',
                borderRadius: '8px',
                overflow: 'hidden',
              }}
            >
              <Box sx={{ p: 1 }}>
                {/* Question Header */}
                <Box
                  sx={{
                    display: 'flex',
                    alignItems: 'flex-start',
                    gap: 2,
                    // mb: 2,
                  }}
                >
                  <Box sx={{ flex: 1 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                      {/* <Typography
                        sx={{
                          fontSize: '12px',
                          color: '#666',
                        }}
                      >
                        Questions
                      </Typography> */}
                    </Box>
                    <Typography
                      sx={{
                        fontFamily: 'Roboto',
                        fontSize: '13px',
                        fontWeight: 500,
                        color: '#000',
                        mb: 1,
                      }}
                    >
                      {/* {question.question} */}
                      {answer.q_id}: {answer.question}
                    </Typography>

                  </Box>
                </Box>

                {/* Answer Options */}
                <FormControl component="fieldset" sx={{ width: '100%' }}>
                  <RadioGroup
                    value={answer.answer || ""}
                    sx={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 0.5 }}
                  >
                    {JSON.parse(answer.options.replace(/'/g, '"')).map((opt: string) => (
                      <FormControlLabel
                        key={opt}
                        value={opt}
                        control={<Radio sx={{ p: 0.5 }} />}
                        label={<Typography sx={{ fontSize: 12 }}>{opt}</Typography>}
                        sx={{ m: 0 }}
                        disabled={answer.answer !== opt}
                      />
                    ))}
                  </RadioGroup>
                </FormControl>
              </Box>
            </Paper>
          ))}
        </Box>
      </Box>
      {/* Action Buttons */}
      <Box sx={{ bgcolor: '#f3faff' }}>
        <Typography
          sx={{
            fontFamily: 'Roboto',
            fontSize: '16px',
            fontWeight: 600,
            color: '#000',
            // mb: 1,
            pl: 2,
            pb: 1,
            pt: 1
          }}
        >
          Want to make changes?
        </Typography>

        <Box
          sx={{
            borderTop: '1px solid #E0E0E0',
            //   bgcolor: 'white',
            p: 2,
            display: 'flex',
            justifyContent: 'flex-start',
            gap: 2,
          }}
        >
          <Button
            variant="outlined"
            sx={{
              textTransform: 'none',
              color: '#0F4977',
              borderColor: '#0F4977',
              px: 3,
              '&:hover': {
                borderColor: '#0F4977',
                bgcolor: 'rgba(15, 73, 119, 0.04)',
              },
            }}
          >
            Cancel
          </Button>
          <Button
            onClick={() => navigate(`/pharmacy-portal/pdf-viewer/${patient_id}/${procedure_name}`)}
            variant="contained"
            sx={{
              textTransform: 'none',
              bgcolor: '#0F4977',
              px: 3,
              '&:hover': {
                bgcolor: '#0D3D63',
              },
            }}
          >
            Edit Clinical Assessment Responses
          </Button>
          <Button
            onClick={() => navigate(`/pharmacy-portal/decision/${pa_status}/${procedure_name}/${patient_id}`)}
            variant="contained"
            sx={{
              textTransform: 'none',
              bgcolor: '#0F4977',
              px: 3,
              '&:hover': {
                bgcolor: '#0D3D63',
              },
            }}
          >
            Decision Guidance
          </Button>
        </Box>
      </Box>
    </Box>
  );
};

export default observer(Summary);
